<script setup lang="ts">
import { useCardMotion } from '../composables/useCardMotion'
import Button from 'primevue/button'

import { computed,ref } from 'vue'
import { Plus,Pencil,Trash2,Check,CalendarDays,Gauge } from 'lucide-vue-next'
import { useGarage } from '../stores/garage'
import { api } from '../services/api'
import { date,number,states,priorities } from '../services/types'
import type { Schedule } from '../services/types'
import ScheduleDialog from '../components/ScheduleDialog.vue'
import FormDatePicker from '../components/FormDatePicker.vue'
import EmptyState from '../components/EmptyState.vue'
const g=useGarage(),open=ref(false),edit=ref<Schedule|null>(null),filter=ref('active'),error=ref(''),month=ref(new Date().toISOString().slice(0,7))
const rows=computed(()=>g.schedules.filter(s=>filter.value==='all'||(filter.value==='active'?!s.completed:s.state===filter.value)))
const monthRows=computed(()=>g.schedules.filter(s=>s.dueDate?.startsWith(month.value)))
async function remove(s:Schedule){if(!confirm('Excluir este agendamento?'))return;try{await api(`/vehicles/${g.selectedId}/schedules/${s.id}`,{method:'DELETE'});await g.refresh()}catch(e){error.value=(e as Error).message}}
async function complete(s:Schedule){try{await api(`/vehicles/${g.selectedId}/schedules/${s.id}`,{method:'PUT',body:JSON.stringify({...s,completed:!s.completed})});await g.refresh()}catch(e){error.value=(e as Error).message}}
const { cardInitial, cardEnter } = useCardMotion()
</script>
<template><template v-if="g.selected"><div class="section-header"><p class="view-description">Um pouco de planejamento. Muitos quilômetros de tranquilidade.</p><Button class="button" @click="edit=null;open=true"><Plus :size="17"/>Programar manutenção</Button></div><p v-if="g.selected.mileage==null" class="info-banner"><Gauge :size="20"/>Informe o hodômetro na visão geral para ativar os alertas por quilometragem.</p><p class="muted">Próxima: até 30 dias ou 1.000 km. Vencida: data passada ou quilometragem atingida. Vale o primeiro limite.</p><div class="schedule-toolbar"><div class="segmented" aria-label="Filtrar agendamentos"><Button v-for="f in [{key:'active',name:'Em aberto'},{key:'Overdue',name:'Vencidas'},{key:'Completed',name:'Concluídas'},{key:'all',name:'Todas'}]" :key="f.key" :class="{active:filter===f.key}" :aria-pressed="filter===f.key" @click="filter=f.key">{{f.name}}</Button></div></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="schedule-list"><article v-for="s in rows" :key="s.id" v-motion :initial="cardInitial" :enter="cardEnter(30)" class="panel schedule-row"><span class="schedule-icon" :class="s.state"><CalendarDays :size="22"/></span><div class="schedule-description"><span class="status-label" :class="s.state">{{states[s.state]}}</span><h2>{{s.description}}</h2><p class="muted">{{s.componentName}}{{s.subcomponentName?' · '+s.subcomponentName:''}} · Prioridade {{priorities[s.priority]?.toLowerCase()}}</p><div class="schedule-dates"><span v-if="s.dueDate"><CalendarDays :size="15"/>{{date(s.dueDate)}}</span><span v-if="s.dueMileage!=null"><Gauge :size="15"/>{{number(s.dueMileage)}} km</span></div></div><div class="record-actions"><Button class="icon-button" :aria-label="s.completed?'Reabrir agendamento':'Concluir agendamento'" @click="complete(s)"><Check :size="18"/></Button><Button class="icon-button" aria-label="Editar agendamento" @click="edit=s;open=true"><Pencil :size="17"/></Button><Button class="icon-button danger" aria-label="Excluir agendamento" @click="remove(s)"><Trash2 :size="17"/></Button></div></article></div><EmptyState v-if="!rows.length" title="Espaço para o próximo cuidado" description="Programe uma manutenção e acompanhe o prazo por aqui."/><section v-motion :initial="cardInitial" :enter="cardEnter(60)" class="panel list-panel calendar-panel"><div class="section-header"><h2>Agenda do mês</h2><label for="calendar-month">Mês<FormDatePicker input-id="calendar-month" v-model="month" month-only required /></label></div><div v-for="s in monthRows" :key="s.id" class="data-row"><span>{{date(s.dueDate)}} · {{s.description}}</span><span class="status-label" :class="s.state">{{states[s.state]}}</span></div><p v-if="!monthRows.length" class="muted">Nenhuma manutenção com data neste mês.</p><small class="muted">Agendamentos apenas por quilometragem aparecem na lista acima.</small></section></template><EmptyState v-else title="Selecione um veículo" description="Adicione um veículo para planejar os próximos cuidados."/><ScheduleDialog v-model:visible="open" :schedule="edit"/></template>
